/* HEXA BATTLEGROUNDS setup — PART 24 OF 32. Run parts in order. Safe to re-run. */ create or replace function spectator_state(p_token text) returns jsonb language plpgsql security definer set search_path = public as $$ declare a arenas; e events; sr sync_rounds; v_recap jsonb; v_show_scores boolean; begin select * into a from arenas where spectator_token = p_token; if a.id is null or p_token is null or length(p_token) < 16 then raise exception 'SPECTATOR_AUTH'; end if; perform _tick(a.id); select * into a from arenas where id = a.id; select * into e from events where id = a.event_id; select * into sr from sync_rounds where id = a.sync_round_id; v_show_scores := a.phase in ('lobby', 'boarding', 'shuttle', 'roles', 'play'); if a.phase in ('finale', 'results', 'ended') and coalesce(a.finale_stage, 'A') >= 'D' then v_recap := jsonb_build_object( 'bargains_accepted', (select count(*) from teams t, jsonb_array_elements(t.bargains) b where t.arena_id = a.id and (b ->> 'accept')::boolean), 'bargains_refused', (select count(*) from teams t, jsonb_array_elements(t.bargains) b where t.arena_id = a.id and not (b ->> 'accept')::boolean), 'betrayals', (select count(*) from alliances where arena_id = a.id and status = 'betrayed'), 'alliances', (select count(*) from alliances where arena_id = a.id and status in ('active', 'ended', 'expired', 'betrayed') and expires_at > created_at and status <> 'expired'), 'codewords_shared', (select count(*) from ledger where arena_id = a.id and kind = 'relay_assist'), 'battles', (select count(*) from battles where arena_id = a.id), 'threat', a.threat); end if; return jsonb_build_object( 'server_now', now(), 'event', jsonb_build_object('name', e.name, 'code', e.code, 'grand_revealed', e.grand_revealed), 'arena', jsonb_build_object('id', a.id, 'number', a.number, 'name', a.name, 'phase', a.phase, 'paused', a.paused, 'shuttle_departed_at', a.shuttle_departed_at, 'shuttle_arrive_at', a.shuttle_arrive_at, 'roles_deadline', a.roles_deadline, 'zone_stage', a.zone_stage, 'zone_next_at', a.zone_next_at, 'finale_stage', a.finale_stage, 'threat', a.threat, 'overlay', a.overlay, 'results_locked', a.results_locked, 'winner_revealed', a.winner_revealed), 'squads', (select coalesce(jsonb_agg(jsonb_build_object('number', t.number, 'name', t.name, 'ready', t.ready, 'bus', t.bus, 'players', (select count(*) from players where team_id = t.id and active), 'hp', t.hp, 'state', t.state, 'points', case when v_show_scores then t.points end, 'location', case when t.jammed_until is null or t.jammed_until < now() then t.location_id end, 'pos', case when t.jammed_until is null or t.jammed_until < now() then to_jsonb(_team_xy(t)) end, 'travel_to', case when t.jammed_until is null or t.jammed_until < now() then t.travel_to end, 'travel_from', case when t.jammed_until is null or t.jammed_until < now() then t.travel_from end, 'travel_started_at', t.travel_started_at, 'travel_arrive_at', t.travel_arrive_at, 'in_battle', exists (select 1 from battles b where b.status = 'active' and (b.attacker_id = t.id or b.defender_id = t.id)), 'sync_solved', case when sr.id is not null then exists (select 1 from mission_instances mi where mi.sync_round_id = sr.id and mi.team_id = t.id and mi.status = 'solved') end ) order by t.number), '[]'::jsonb) from teams t where t.arena_id = a.id), 'airdrops', (select coalesce(jsonb_agg(jsonb_build_object('location', location_id, 'tier', tier, 'expires_at', expires_at)), '[]'::jsonb) from airdrops where arena_id = a.id and status = 'open'), 'battles', (select coalesce(jsonb_agg(jsonb_build_object('attacker', (select number from teams where id = b.attacker_id), 'defender', (select number from teams where id = b.defender_id), 'weapon', b.weapon, 'location', b.location_id, 'x', b.x, 'y', b.y, 'deadline', b.deadline)), '[]'::jsonb) from battles b where b.arena_id = a.id and b.status = 'active'), 'sync', case when sr.id is not null then jsonb_build_object('kind', sr.kind, 'stage', sr.stage, 'deadline', sr.deadline, 'title', (select title from mission_templates where id = sr.template_id), 'solved', (select count(*) from mission_instances where sync_round_id = sr.id and status = 'solved'), 'total', (select count(*) from mission_instances where sync_round_id = sr.id)) end, 'story', (select coalesce(jsonb_agg(jsonb_build_object('kind', kind, 'title', title, 'body', body, 'at', at) order by at desc), '[]'::jsonb) from (select * from story_events where arena_id = a.id order by at desc limit 3) s), 'feed', (select coalesce(jsonb_agg(jsonb_build_object('id', id, 'type', type, 'payload', payload, 'at', at) order by id desc), '[]'::jsonb) from (select * from game_feed where arena_id = a.id order by id desc limit 30) f), 'recap', v_recap, 'results', case when a.winner_revealed then a.results end, 'grand', case when e.grand_revealed then _event_standings(e.id) end ); end $$; create or replace function host_overview(p_token text) returns jsonb language plpgsql security definer set search_path = public as $$ declare v_ev uuid; e events; r record; begin v_ev := _auth_host(p_token); for r in select id from arenas where event_id = v_ev loop perform _tick(r.id); end loop; select * into e from events where id = v_ev; return jsonb_build_object( 'server_now', now(), 'event', jsonb_build_object('id', e.id, 'code', e.code, 'name', e.name, 'settings', _defaults() || e.settings, 'grand_revealed', e.grand_revealed, 'seed', e.mission_seed), 'arenas', (select coalesce(jsonb_agg(to_jsonb(a) - 'last_tick_at' order by a.number), '[]'::jsonb) from arenas a where a.event_id = v_ev), 'teams', (select coalesce(jsonb_agg(jsonb_build_object( 'id', t.id, 'number', t.number, 'name', t.name, 'arena_id', t.arena_id, 'ready', t.ready, 'roster_locked', t.roster_locked, 'bus', t.bus, 'hp', t.hp, 'shield', t.shield, 'coins', t.coins, 'points', t.points, 'trust', t.trust, 'final_points', t.final_points, 'missions', t.missions_completed, 'battles', t.battle_wins, 'location', t.location_id, 'state', t.state, 'travel_to', t.travel_to, 'pos', to_jsonb(_team_xy(t)), 'jammed', t.jammed_until > now(), 'protected', t.protected_until > now(), 'players', (select coalesce(jsonb_agg(jsonb_build_object('id', p.id, 'name', p.display_name, 'role', p.role, 'online', p.last_seen_at > now() - interval '25 seconds') order by p.joined_at), '[]'::jsonb) from players p where p.team_id = t.id and p.active), 'inventory', (select coalesce(jsonb_object_agg(item_id, qty), '{}'::jsonb) from inventory where team_id = t.id and qty > 0), 'activity', (select jsonb_build_object('id', mi.id, 'kind', mi.kind, 'title', mt.title, 'template', mt.id, 'attempts_left', mi.attempts_left, 'deadline', mi.deadline, 'hint_used', mi.hint_used, 'answer', mt.parts, 'relay_key', mi.relay_key, 'explanation', mt.explanation) from mission_instances mi join mission_templates mt on mt.id = mi.template_id where mi.team_id = t.id and mi.status = 'active' order by (mi.kind = 'battle') desc, mi.created_at desc limit 1) ) order by t.number), '[]'::jsonb) from teams t where t.event_id = v_ev), 'battles', (select coalesce(jsonb_agg(jsonb_build_object('id', b.id, 'arena_id', b.arena_id, 'weapon', b.weapon, 'attacker', (select number from teams where id = b.attacker_id), 'defender', (select number from teams where id = b.defender_id), 'deadline', b.deadline)), '[]'::jsonb) from battles b join arenas a on a.id = b.arena_id where a.event_id = v_ev and b.status = 'active'), 'airdrops', (select coalesce(jsonb_agg(jsonb_build_object('id', d.id, 'arena_id', d.arena_id, 'location', d.location_id, 'tier', d.tier, 'status', d.status, 'expires_at', d.expires_at)), '[]'::jsonb) from airdrops d join arenas a on a.id = d.arena_id where a.event_id = v_ev and d.status = 'open'), 'sync_rounds', (select coalesce(jsonb_agg(jsonb_build_object('id', s.id, 'arena_id', s.arena_id, 'stage', s.stage, 'kind', s.kind, 'deadline', s.deadline, 'status', s.status, 'solved', (select count(*) from mission_instances where sync_round_id = s.id and status = 'solved'), 'total', (select count(*) from mission_instances where sync_round_id = s.id))), '[]'::jsonb) from sync_rounds s join arenas a on a.id = s.arena_id where a.event_id = v_ev and s.started_at > now() - interval '30 minutes'), 'reports', (select count(*) from chat_messages c join arenas a on a.id = c.arena_id where a.event_id = v_ev and c.reported and not c.hidden), 'metrics', jsonb_build_object( 'players_online', (select count(*) from players p join teams t on t.id = p.team_id where t.event_id = v_ev and p.active and p.last_seen_at > now() - interval '25 seconds'), 'players_total', (select count(*) from players p join teams t on t.id = p.team_id where t.event_id = v_ev and p.active), 'squads_ready', (select count(*) from teams where event_id = v_ev and ready), 'submissions_5m', (select count(*) from submissions s join teams t on t.id = s.team_id where t.event_id = v_ev and s.at > now() - interval '5 minutes'), 'wrong_5m', (select count(*) from submissions s join teams t on t.id = s.team_id where t.event_id = v_ev and not s.correct and s.at > now() - interval '5 minutes'), 'missions_solved', (select count(*) from mission_instances mi join teams t on t.id = mi.team_id where t.event_id = v_ev and mi.status = 'solved'), 'missions_failed', (select count(*) from mission_instances mi join teams t on t.id = mi.team_id where t.event_id = v_ev and mi.status in ('failed', 'expired')), 'host_errors', (select count(*) from audit_log where event_id = v_ev and not ok and action <> 'login_failed')), 'feed', (select coalesce(jsonb_agg(jsonb_build_object('arena_id', f.arena_id, 'type', f.type, 'payload', f.payload, 'at', f.at) order by f.id desc), '[]'::jsonb) from (select g.* from game_feed g join arenas a on a.id = g.arena_id where a.event_id = v_ev order by g.id desc limit 40) f) ); end $$; create or replace function _host_exec_p0(p_ev uuid, p_arena uuid, p_cmd text, p_args jsonb, p_reason text) returns jsonb language plpgsql as $$ declare a arenas; e events; t teams; v_delta interval; v_pin text; v_salt text; v_out jsonb := '[]'::jsonb; i int; j int; begin select * into e from events where id = p_ev; if p_arena is not null then select * into a from arenas where id = p_arena; end if; case p_cmd when 'set_phase', 'next_phase' then if a.phase <> 'play' then raise exception 'WRONG_PHASE'; end if; i := case when p_cmd = 'next_phase' then a.match_phase + 1 else (p_args ->> 'phase')::int end; if i is null or i < 0 or i > 4 then raise exception 'BAD_PHASE'; end if; perform _set_match_phase(a.id, i); perform _tick(a.id, true); return jsonb_build_object('phase', i); when 'hide_rankings' then update arenas set overlay = overlay || jsonb_build_object('hide_rankings', coalesce((p_args ->> 'on')::boolean, true)) where id = a.id; when 'reset_pin' then select * into t from teams where id = (p_args ->> 'team_id')::uuid and event_id = p_ev for update; if t.id is null then raise exception 'NOT_FOUND'; end if; v_pin := _new_pin(_cfg(p_ev, 'pin_length')); v_salt := _new_token(); update teams set pin_salt = v_salt, pin_hash = _hash(v_salt || v_pin) where id = t.id; delete from pin_failures where event_id = p_ev and team_number = t.number; return jsonb_build_object('number', t.number, 'name', t.name, 'pin', v_pin); when 'red_zone' then return _red_spawn(a.id, (p_args ->> 'x')::float8, (p_args ->> 'y')::float8); when 'red_cancel' then update arenas set red_x = null, red_y = null, red_r = null, red_at = null where id = a.id; perform _zone_publish(a.id); else raise exception 'UNKNOWN_COMMAND'; end case; return '{}'::jsonb; end $$; create or replace function host_command(p_token text, p_arena uuid, p_cmd text, p_args jsonb default '{}'::jsonb, p_reason text default null) returns jsonb language plpgsql security definer set search_path = public as $$ declare v_ev uuid; v_ids uuid[]; v_id uuid; v_out jsonb := '{}'::jsonb; v_err text; v_res jsonb; v_delta interval; v_logargs jsonb; v_all_ok text[] := array['open_boarding','assign_buses','drive','finalize_roles','pause','resume','broadcast','clear_overlay', 'blackout','countdown','story','bargain','zone_warn','zone_now','zone_cancel','zone_set','spawn_airdrop','begin_finale', 'finale_stage','launch_sync','close_sync','lock_results','reveal_winner','end_game','reveal_squad00', 'next_phase','set_phase','hide_rankings','red_zone','red_cancel']; v_new text[] := array['set_phase','next_phase','hide_rankings','reset_pin','red_zone','red_cancel']; begin v_ev := _auth_host(p_token); p_args := coalesce(p_args, '{}'::jsonb); v_logargs := p_args - 'pin'; if p_arena is null then if p_cmd = any(v_all_ok) then select array_agg(id order by number) into v_ids from arenas where event_id = v_ev; else v_ids := array[null::uuid]; end if; else if not exists (select 1 from arenas where id = p_arena and event_id = v_ev) then raise exception 'BAD_ARENA'; end if; v_ids := array[p_arena]; end if; foreach v_id in array v_ids loop begin v_delta := null; if p_cmd = 'resume' then select now() - paused_at into v_delta from arenas where id = v_id and paused; end if; if p_cmd in ('open_boarding', 'assign_buses', 'drive') and v_id is not null and not exists (select 1 from teams where arena_id = v_id and ready) then raise exception 'NO_READY_SQUADS'; end if; if p_cmd = any(v_new) then v_res := _host_exec_p0(v_ev, v_id, p_cmd, p_args, p_reason); elsif p_cmd = 'clear_overlay' then update arenas set overlay = (select coalesce(jsonb_object_agg(k, v), '{}'::jsonb) from jsonb_each(overlay) as x(k, v) where k in ('match', 'zone', 'world', 'red')) where id = v_id; v_res := '{}'::jsonb; else v_res := _host_exec(v_ev, v_id, p_cmd, p_args, p_reason); end if; if p_cmd = 'resume' and v_delta is not null then update arenas set phase_next_at = phase_next_at + v_delta, phase_started_at = phase_started_at + v_delta, shuttle_departed_at = shuttle_departed_at + v_delta, overlay = case when overlay ? 'match' and overlay #>> '{match,next_at}' is not null then jsonb_set(overlay, '{match,next_at}', to_jsonb((overlay #>> '{match,next_at}')::timestamptz + v_delta)) else overlay end where id = v_id; elsif p_cmd = 'begin_finale' then update arenas set match_phase = 5, phase_started_at = now(), phase_next_at = null, overlay = overlay || jsonb_build_object('match', jsonb_build_object('phase', 5, 'started_at', now(), 'next_at', null, 'zone_target', 5)) where id = v_id; perform _feed(v_id, 'phase.started', jsonb_build_object('phase', 5)); elsif p_cmd = 'zone_cancel' then update arenas set zone_hold = true where id = v_id; elsif p_cmd in ('zone_warn', 'zone_now', 'zone_set') then update arenas set zone_hold = false where id = v_id; elsif p_cmd = 'reset_arena' then update arenas set match_phase = 0, phase_started_at = null, phase_next_at = null, zone_hold = false, red_x = null, red_y = null, red_r = null, red_at = null, last_red_at = null where id = v_id; update teams set zone_hit_at = null, travel_fx = null, travel_fy = null where arena_id = v_id; end if; v_out := v_out || jsonb_build_object(coalesce(v_id::text, 'event'), v_res); insert into audit_log(event_id, arena_id, actor, action, args, reason) values (v_ev, v_id, 'host', p_cmd, v_logargs, p_reason); exception when others then v_err := sqlerrm; insert into audit_log(event_id, arena_id, actor, action, args, reason, ok, error) values (v_ev, v_id, 'host', p_cmd, v_logargs, p_reason, false, v_err); if array_length(v_ids, 1) = 1 then return jsonb_build_object('ok', false, 'error', v_err); end if; v_out := v_out || jsonb_build_object(coalesce(v_id::text, 'event'), jsonb_build_object('error', v_err)); end; if v_id is not null then perform _zone_publish(v_id); perform _ping_arena(v_id, 'host'); end if; end loop; return jsonb_build_object('ok', true, 'result', v_out); end $$; drop function if exists host_create_trial(text, text, text, int); drop function if exists host_trial_status(text); update arenas set overlay = overlay - 'trial' where overlay ? 'trial'; do $$ declare r record; begin for r in select id from arenas loop perform _zone_publish(r.id); end loop; end $$; do $$ declare f record; begin for f in select p.oid::regprocedure as sig, p.proname from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.prokind = 'f' loop execute format('revoke all on function %s from public', f.sig); begin execute format('revoke all on function %s from anon, authenticated', f.sig); exception when undefined_object then null; end; if f.proname = any(array['map_data', 'join_team', 'claim_role', 'player_state', 'captain_move', 'captain_explore', 'captain_submit', 'captain_hint', 'captain_use_item', 'captain_buy', 'captain_attack', 'captain_claim_airdrop', 'captain_chat', 'captain_block', 'captain_report', 'captain_alliance', 'captain_bargain', 'host_create_event', 'host_login', 'host_generate_teams', 'host_import_teams', 'host_overview', 'host_command', 'host_settings', 'host_missions', 'host_save_mission', 'host_test_answer', 'host_chat_log', 'host_audit', 'host_export', 'spectator_state', 'host_roster', 'captain_steer']) then begin execute format('grant execute on function %s to anon, authenticated', f.sig); exception when undefined_object then null; end; end if; end loop; end $$; alter table mission_instances add column if not exists revealed jsonb not null default '{}'::jsonb;
